package at.htl.flowstate.Components.SpriteComponents;

import at.htl.flowstate.Assets;
import at.htl.flowstate.Visuals.FrameSprite;
import at.htl.flowstate.Visuals.Frames;
import com.almasb.fxgl.entity.component.Component;
import javafx.scene.Node;
import javafx.scene.effect.ColorAdjust;
import javafx.scene.effect.DropShadow;
import javafx.scene.effect.Effect;
import javafx.scene.image.ImageView;
import javafx.scene.paint.Color;

/**
 * Animated slime sprite (player and enemies) built from the strips generated by tools/art/slimes.py
 * and tools/art/player_slime.py: {@code <prefix>_<anim>.png}, 64x64 frames (the count comes from the
 * strip width), shown at x2 and anchored at the bottom centre of the 40x80 hitbox.
 * <p>
 * Callers report a continuous {@link State} every frame and trigger one-shots (land, attack, hurt, ...).
 * A one-shot plays to its end unless a state with more {@link State#force} than the one-shot's
 * {@link Shot#resist} comes in (a dash cuts an attack short, a landing never cuts a hurt flinch).
 * Enemies only use IDLE / WALK / AIR, land and attack; the player (extended = true) has the full set
 * and fidgets after standing still for a while.
 */
public class SpriteComponent extends Component {
    public enum State {
        IDLE(0), WALK(1), RUN(1), BLOCK(1), CHARGE(1), AIR(2), GLIDE(2), LEVITATE(2), DASH(4), DIVE(4);

        final int force;
        State(int force) { this.force = force; }
    }

    private enum Shot {
        FIDGET(0, 8), LAND(1, 18), SLAM(1, 16), TAKEOFF(2, 20), ATTACK(3, 18), SHOOT(3, 16), CAST(3, 14),
        HURT(5, 14), DEATH(99, 9);

        final int resist;
        final double fps;
        Shot(int resist, double fps) { this.resist = resist; this.fps = fps; }
    }

    private static final int SCALE = 2;
    private static final double FRAME = 64 * SCALE;
    // hitbox is 40x80; the art's bottom anchor is (32, 63) in the 64x64 frame
    private static final double OFFSET_X = 20 - 32 * SCALE;
    private static final double OFFSET_Y = 80 - 63 * SCALE;
    private static final double FLASH_TIME = 0.12;
    private static final double TURN_SPEED = 14;
    private static final double FIDGET_AFTER = 5;          // seconds of standing still
    private static final double FIDGET_AGAIN = 8;

    private final String prefix;
    private final Frames idle, walk, air, land, attack;
    // player only (null for enemies)
    private final Frames run, dash, levitate, glide, dive, block, charge;
    private final Frames takeoff, hurt, death, shoot, cast, slam, fidget;

    private final FrameSprite sprite;
    private final ImageView frozen;
    private final FrameSprite stunStars;
    private final FrameSprite shield;
    private final Effect baseEffect;
    private final ColorAdjust flashEffect = new ColorAdjust(0, -0.4, 0.75, 0);

    private int facing = 1;
    private double scaleX = 1;
    private double flashLeft = 0;
    private boolean blinking = false;
    private double blinkTime = 0;
    private Shot shot = null;
    private State state = State.IDLE;
    private double stillTime = 0;
    private double fidgetAt = FIDGET_AFTER;
    private boolean dead = false;

    /** Enemy sprite (idle / walk / air / land, optional attack). */
    public SpriteComponent(String prefix, boolean hasAttack, boolean glow) {
        this(prefix, hasAttack, glow, false);
    }

    /** {@code extended}: load the player's full animation set (tools/art/player_slime.py). */
    public SpriteComponent(String prefix, boolean hasAttack, boolean glow, boolean extended) {
        this.prefix = prefix;
        idle = strip("idle");
        walk = strip("walk");
        air = strip("air");
        land = strip("land");
        attack = hasAttack ? strip("attack") : null;

        run = extended ? strip("run") : null;
        dash = extended ? strip("dash") : null;
        levitate = extended ? strip("levitate") : null;
        glide = extended ? strip("glide") : null;
        dive = extended ? strip("dive") : null;
        block = extended ? strip("block") : null;
        charge = extended ? strip("charge") : null;
        takeoff = extended ? strip("takeoff") : null;
        hurt = extended ? strip("hurt") : null;
        death = extended ? strip("death") : null;
        shoot = extended ? strip("shoot") : null;
        cast = extended ? strip("cast") : null;
        slam = extended ? strip("slam") : null;
        fidget = extended ? strip("fidget") : null;

        sprite = new FrameSprite(idle).loop(idle, 8);
        place(sprite, OFFSET_X, OFFSET_Y);

        frozen = Assets.sprite("FrozenOverlay.png", SCALE);
        frozen.setOpacity(0.85);
        place(frozen, OFFSET_X, OFFSET_Y);
        frozen.setVisible(false);

        Frames stars = Assets.frames("StunStars.png", 4, SCALE);
        stunStars = new FrameSprite(stars).loop(stars, 8);
        place(stunStars, 20 - stars.width() / 2, -6 - stars.height());
        stunStars.setVisible(false);

        Frames bubble = Assets.frames("MagicShield.png", 4, SCALE);
        shield = new FrameSprite(bubble).loop(bubble, 6);
        place(shield, 20 - bubble.width() / 2, 40 - bubble.height() / 2 + 6);
        shield.setVisible(false);

        if (glow) {
            DropShadow shadow = new DropShadow(14, Color.rgb(255, 130, 40, 0.5));   // ember glow of the tar slime
            shadow.setSpread(0.25);
            baseEffect = shadow;
        } else {
            baseEffect = null;
        }
        sprite.setEffect(baseEffect);
    }

    /** {@code <prefix>_<name>.png} with as many frames as fit in its width. */
    private Frames strip(String name) {
        String file = prefix + "_" + name + ".png";
        int count = (int) Math.round(Assets.pixels(file, SCALE).getWidth() / FRAME);
        return Assets.frames(file, Math.max(1, count), SCALE);
    }

    private static void place(Node node, double x, double y) {
        node.setTranslateX(x);
        node.setTranslateY(y);
    }

    @Override
    public void onAdded() {
        entity.getViewComponent().addChild(sprite);
        entity.getViewComponent().addChild(frozen);
        entity.getViewComponent().addChild(stunStars);
        entity.getViewComponent().addChild(shield);
    }

    @Override
    public void onUpdate(double tpf) {
        // smooth turn: squash through 0 instead of snapping
        scaleX += (facing - scaleX) * Math.min(1, tpf * TURN_SPEED);
        if (Math.abs(facing - scaleX) < 0.02) scaleX = facing;
        double s = Math.abs(scaleX) < 0.15 ? Math.signum(scaleX == 0 ? facing : scaleX) * 0.15 : scaleX;
        sprite.setScaleX(s);
        frozen.setScaleX(s);

        if (flashLeft > 0) {
            flashLeft -= tpf;
            if (flashLeft <= 0) sprite.setEffect(baseEffect);
        }
        if (blinking) {
            blinkTime += tpf;
            sprite.setOpacity(((int) (blinkTime * 14)) % 2 == 0 ? 1 : 0.35);
        }

        // standing still for a while: play the idle fidget now and then
        if (fidget != null && state == State.IDLE && shot == null && !dead) {
            stillTime += tpf;
            if (stillTime >= fidgetAt) {
                stillTime = 0;
                fidgetAt = FIDGET_AGAIN + Math.random() * 4;
                play(Shot.FIDGET, fidget);
            }
        }
    }

    //-----state from the movement code-----
    public void setFacing(int direction) {
        if (dead) return;
        if (direction != 0) facing = direction > 0 ? 1 : -1;
    }

    /**
     * Continuous state, reported every frame. {@code value} is the vertical velocity for AIR and the
     * charge progress (0..1) for CHARGE. Ignored while a stronger one-shot is playing.
     */
    public void setState(State next, double value) {
        if (dead) return;
        if (next != State.IDLE) {
            stillTime = 0;
            fidgetAt = FIDGET_AFTER;
        }
        state = next;
        if (shot != null) {
            if (next.force <= shot.resist) return;
            shot = null;
        }
        switch (next) {
            case IDLE -> loop(idle, 8);
            case WALK -> loop(walk, 12);
            case RUN -> loop(run != null ? run : walk, run != null ? 14 : 12);
            case BLOCK -> loop(block != null ? block : idle, 6);
            case DASH -> loop(dash != null ? dash : walk, 20);
            case LEVITATE -> loop(levitate != null ? levitate : idle, 8);
            case GLIDE -> loop(glide != null ? glide : idle, 8);
            case DIVE -> {
                if (dive != null) loop(dive, 12);
                else sprite.show(air, 3);
            }
            case CHARGE -> {
                if (charge == null) loop(idle, 8);
                else sprite.show(charge, (int) Math.min(charge.count() - 1, Math.max(0, value) * charge.count()));
            }
            case AIR -> sprite.show(air, value < -350 ? 0 : value < -80 ? 1 : value < 120 ? 2 : 3);
        }
    }

    private void loop(Frames frames, double fps) {
        if (!sprite.isPlaying(frames)) sprite.loop(frames, fps);
    }

    /** Starts a one-shot unless a stronger one is playing. Missing strips (enemies) are skipped. */
    private void play(Shot next, Frames frames) {
        play(next, frames, next.fps);
    }

    private void play(Shot next, Frames frames, double fps) {
        if (frames == null || dead) return;
        if (shot != null && next.resist < shot.resist) return;
        shot = next;
        sprite.once(frames, fps, () -> { if (shot == next) shot = null; });
    }

    //-----one-shots-----
    public void playLand() { play(Shot.LAND, land); }

    /** Melee swing (player) / shot (Hunter). */
    public void playAttack() { play(Shot.ATTACK, attack, run != null ? Shot.ATTACK.fps : 12); }

    public void playTakeoff() { play(Shot.TAKEOFF, takeoff); }

    public void playShoot() { play(Shot.SHOOT, shoot); }

    public void playCast() { play(Shot.CAST, cast); }

    public void playHurt() { play(Shot.HURT, hurt); }

    /** Hammer slam landing. Falls back to the normal landing. */
    public void playSlam() { play(Shot.SLAM, slam != null ? slam : land); }

    /** Melts into a puddle and stays there; {@code onDone} runs once the last frame shows. */
    public void playDeath(Runnable onDone) {
        if (dead) return;
        setBlinking(false);
        if (death == null) {
            dead = true;
            if (onDone != null) onDone.run();
            return;
        }
        shot = Shot.DEATH;
        dead = true;
        sprite.once(death, Shot.DEATH.fps, onDone);
    }

    public boolean isDead() { return dead; }

    //-----feedback & overlays-----
    public void flash() {
        flashLeft = FLASH_TIME;
        flashEffect.setInput(baseEffect);
        sprite.setEffect(flashEffect);
    }

    public void setBlinking(boolean on) {
        if (dead) on = false;
        if (blinking == on) return;
        blinking = on;
        blinkTime = 0;
        if (!on) sprite.setOpacity(1);
    }

    public void setFrozen(boolean on) {
        frozen.setVisible(on);
        sprite.setPaused(on);
    }

    public void setStunned(boolean on) {
        stunStars.setVisible(on);
    }

    public void setShield(boolean on) {
        shield.setVisible(on);
    }
}
